INSERT INTO test_cases (id, project_id, title, description, priority, type, active, created_at) VALUES
('40000000-0000-0000-0001-000000000001', '10000000-0000-0000-0000-000000000001', 'Guest checkout completes with a valid card', 'A customer with no account reaches the confirmation page.', 'CRITICAL', 'E2E', true, '2026-02-09 09:00:00'),
('40000000-0000-0000-0001-000000000002', '10000000-0000-0000-0000-000000000001', 'Registered customer checks out with a saved card', 'A stored payment method completes without re-entry.', 'CRITICAL', 'E2E', true, '2026-02-09 09:00:00'),
('40000000-0000-0000-0001-000000000003', '10000000-0000-0000-0000-000000000001', 'Expired card is declined with a readable message', 'The gateway decline is translated for the customer.', 'HIGH', 'API', true, '2026-02-09 09:00:00'),
('40000000-0000-0000-0001-000000000004', '10000000-0000-0000-0000-000000000001', 'Insufficient funds decline is surfaced to the customer', 'The customer is told the card was declined and can retry.', 'HIGH', 'API', true, '2026-02-09 09:00:00'),
('40000000-0000-0000-0001-000000000005', '10000000-0000-0000-0000-000000000001', 'Order total recalculates when a promo code is applied', 'Discount and total update without a page reload.', 'HIGH', 'UI', true, '2026-02-09 09:00:00'),
('40000000-0000-0000-0001-000000000006', '10000000-0000-0000-0000-000000000001', 'Expired promo code is rejected', 'An out of date code leaves the total unchanged.', 'MEDIUM', 'API', true, '2026-02-09 09:00:00'),
('40000000-0000-0000-0001-000000000007', '10000000-0000-0000-0000-000000000001', 'Tax is calculated for an Illinois shipping address', 'State and local rates apply to the order subtotal.', 'HIGH', 'INTEGRATION', true, '2026-02-09 09:00:00'),
('40000000-0000-0000-0001-000000000008', '10000000-0000-0000-0000-000000000001', 'Free shipping applies at the correct subtotal', 'The threshold is applied before tax, not after.', 'MEDIUM', 'INTEGRATION', true, '2026-02-09 09:00:00'),
('40000000-0000-0000-0001-000000000009', '10000000-0000-0000-0000-000000000001', 'Cart contents persist across a session timeout', 'Returning after a timeout restores the same cart.', 'MEDIUM', 'E2E', true, '2026-02-09 09:00:00'),
('40000000-0000-0000-0001-000000000010', '10000000-0000-0000-0000-000000000001', 'Duplicate submit does not create two orders', 'A double click produces exactly one order record.', 'CRITICAL', 'API', true, '2026-02-09 09:00:00'),
('40000000-0000-0000-0001-000000000011', '10000000-0000-0000-0000-000000000001', 'Inventory is reserved when payment authorises', 'Stock is held as soon as authorisation succeeds.', 'CRITICAL', 'INTEGRATION', true, '2026-02-09 09:00:00'),
('40000000-0000-0000-0001-000000000012', '10000000-0000-0000-0000-000000000001', 'Inventory is released when payment fails', 'A declined payment returns stock to the pool.', 'HIGH', 'INTEGRATION', true, '2026-02-09 09:00:00'),
('40000000-0000-0000-0001-000000000013', '10000000-0000-0000-0000-000000000001', 'Order confirmation email is queued', 'A confirmation job is enqueued within the request.', 'MEDIUM', 'INTEGRATION', true, '2026-02-09 09:00:00'),
('40000000-0000-0000-0001-000000000014', '10000000-0000-0000-0000-000000000001', 'Refund returns funds to the original card', 'A full refund reverses the original capture.', 'HIGH', 'API', true, '2026-02-09 09:00:00'),
('40000000-0000-0000-0001-000000000015', '10000000-0000-0000-0000-000000000001', 'Partial refund adjusts the order total', 'The remaining balance matches the refunded amount.', 'HIGH', 'API', true, '2026-02-09 09:00:00'),
('40000000-0000-0000-0001-000000000016', '10000000-0000-0000-0000-000000000001', 'Address validation rejects an incomplete postcode', 'A short postcode is refused before payment.', 'MEDIUM', 'UI', true, '2026-02-09 09:00:00'),
('40000000-0000-0000-0001-000000000017', '10000000-0000-0000-0000-000000000001', 'Checkout is usable on a mobile viewport', 'All fields and the pay button are reachable at 375px.', 'MEDIUM', 'UI', true, '2026-02-09 09:00:00'),
('40000000-0000-0000-0001-000000000018', '10000000-0000-0000-0000-000000000001', 'Payment webhook retries on a server error', 'A 500 from the handler is retried with backoff.', 'HIGH', 'INTEGRATION', true, '2026-02-09 09:00:00'),
('40000000-0000-0000-0001-000000000019', '10000000-0000-0000-0000-000000000001', 'Audit log records every payment state change', 'Authorise, capture and refund each write an entry.', 'HIGH', 'API', true, '2026-02-09 09:00:00'),
('40000000-0000-0000-0001-000000000020', '10000000-0000-0000-0000-000000000001', 'Checkout rejects a request without a CSRF token', 'A missing token returns 403 and no order is created.', 'CRITICAL', 'API', true, '2026-02-09 09:00:00'),
('40000000-0000-0000-0002-000000000001', '10000000-0000-0000-0000-000000000002', 'App launches to the home screen', 'A cold start reaches the home screen without error.', 'CRITICAL', 'SMOKE', true, '2026-03-23 09:00:00'),
('40000000-0000-0000-0002-000000000002', '10000000-0000-0000-0000-000000000002', 'Customer signs in with a valid password', 'Valid credentials return a session token.', 'CRITICAL', 'E2E', true, '2026-03-23 09:00:00'),
('40000000-0000-0000-0002-000000000003', '10000000-0000-0000-0000-000000000002', 'Biometric sign-in unlocks the app', 'Face and fingerprint unlock restore the session.', 'HIGH', 'UI', true, '2026-03-23 09:00:00'),
('40000000-0000-0000-0002-000000000004', '10000000-0000-0000-0000-000000000002', 'Order history lists past orders', 'Orders appear newest first with correct totals.', 'HIGH', 'API', true, '2026-03-23 09:00:00'),
('40000000-0000-0000-0002-000000000005', '10000000-0000-0000-0000-000000000002', 'Push notification opens the matching order', 'Tapping a notification deep links to that order.', 'MEDIUM', 'E2E', true, '2026-03-23 09:00:00'),
('40000000-0000-0000-0002-000000000006', '10000000-0000-0000-0000-000000000002', 'App recovers from an offline state', 'Restoring connectivity refreshes cached screens.', 'MEDIUM', 'REGRESSION', true, '2026-03-23 09:00:00'),
('40000000-0000-0000-0002-000000000007', '10000000-0000-0000-0000-000000000002', 'Profile update persists after a restart', 'An edited profile survives a full app restart.', 'MEDIUM', 'E2E', true, '2026-03-23 09:00:00'),
('40000000-0000-0000-0002-000000000008', '10000000-0000-0000-0000-000000000002', 'Sign out clears the stored session token', 'No token remains in secure storage after sign out.', 'HIGH', 'UNIT', true, '2026-03-23 09:00:00');
